for proj, pkgs in sorted(baseline.items()):
    print(f'  {proj}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg}: requested={ver[\"requested\"]} resolved={ver[\"resolved\"]}')

print()
print('=== AFTER CPM ===')
for proj, pkgs in sorted(after.items()):
    print(f'  {proj}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg}: requested={ver[\"requested\"]} resolved={ver[\"resolved\"]}')

print()
print('=== CHANGES ===')
for proj in sorted(set(list(baseline.keys()) + list(after.keys()))):
    b = baseline.get(proj, {})
    a = after.get(proj, {})
    for pkg in sorted(set(list(b.keys()) + list(a.keys()))):
